/**
 * /waiver-advisor — the "Weekly IDP streaming" mode, end to end in the browser
 * (owner directive 2026-10-29, Workstream G; flag `idp_streaming`, default OFF).
 *
 * POST /api/waiver/advisor and POST /api/waiver/streaming are answered by
 * page.route — both flags ship OFF, so the live stack would only ever show
 * "not available".  The streaming answers are the REAL composer's output
 * (frontend/__tests__/fixtures/idp-streaming/*.json, generated by
 * tests/waivers/streaming_ui_payloads.py and byte-pinned against it); the mock
 * re-stamps only league and team so the page's stale-answer guard accepts them.
 * What this pins is the browser half: the mode exists only behind the gate,
 * picking a real team from the loaded rosters sends that team, the controls
 * reach the backend (the dynasty budget changes the plan the backend returns),
 * the explicit no-move state, the boards render, no sideways scroll at 390 px,
 * and axe is clean on the populated state.  Runs on every project (desktop and
 * phone, including WebKit mobile-390).
 *
 * This is NOT acceptance scenario 10 (a real roster against real projections):
 * that needs the flags on against production data, which is an owner action.
 *
 * Auth: test-only session fixture (skips when E2E_TEST_SECRET is unset).
 */
const fs = require("fs");
const path = require("path");
const { test, expect } = require("../helpers/auth-fixture");
const { pageUrl, awaitStreamSettled, isNavigationAbortedFetch } = require("../helpers/journey");
const AxeBuilder = require("@axe-core/playwright").default;

test.use({ serviceWorkers: "block" });

const TAGS = ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"];
const FIXTURES = path.resolve(__dirname, "../../../frontend/__tests__/fixtures/idp-streaming");
const load = (name) => JSON.parse(fs.readFileSync(path.join(FIXTURES, `${name}.json`), "utf-8"));
const RECOMMEND = load("recommend");
const LIMITED = load("budget-limited");
const NO_MOVE = load("no-move");

function json(route, status, body) {
  return route.fulfill({
    status,
    contentType: "application/json",
    headers: { "Cache-Control": "no-store" },
    body: JSON.stringify(body),
  });
}

/** Mock both endpoints; returns the streaming request bodies that carried a team. */
async function mockEndpoints(page, { streamingOff = false } = {}) {
  const calls = [];
  await page.route(
    (url) => url.pathname === "/api/waiver/advisor",
    (route) => {
      const body = route.request().postDataJSON() || {};
      if (!body.teamOwnerId) return json(route, 400, { error: "team_required", leagueKey: body.leagueKey });
      return json(route, 200, {
        version: "waiver-advisor/2026-10-27.v1",
        leagueKey: body.leagueKey,
        team: { ownerId: body.teamOwnerId },
        candidates: [],
        census: { shown: 0, matchingFilter: 0 },
        faab: { state: "unknown", bidMethodology: "market_aware" },
        posture: { state: "unavailable", reason: "league_bundle_not_warm" },
        plan: null,
        methodologyDependencies: [],
        notes: [],
      });
    },
  );
  await page.route(
    (url) => url.pathname === "/api/waiver/streaming",
    (route) => {
      if (streamingOff) return json(route, 503, { error: "feature_disabled", flag: "idp_streaming" });
      const body = route.request().postDataJSON() || {};
      if (!body.teamOwnerId) return json(route, 400, { error: "team_required", leagueKey: body.leagueKey });
      calls.push(body);
      const fixture =
        body.position === "DL" ? NO_MOVE : Number(body.dynastyBudget) >= 300 ? RECOMMEND : LIMITED;
      return json(route, 200, {
        ...fixture,
        leagueKey: body.leagueKey || fixture.leagueKey,
        team: { ...fixture.team, ownerId: body.teamOwnerId },
      });
    },
  );
  return calls;
}

async function noPageOverflow(page) {
  const sizes = await page.evaluate(() => ({
    document: document.documentElement.scrollWidth,
    viewport: document.documentElement.clientWidth,
  }));
  expect(sizes.document, "the page must not scroll sideways").toBeLessThanOrEqual(sizes.viewport + 1);
}

async function openAdvisorWithTeam(page) {
  await page.goto(pageUrl("/waiver-advisor"));
  await awaitStreamSettled(page);
  const root = page.getByTestId("waiver-advisor");
  await expect(root).toBeVisible({ timeout: 60_000 });
  // Pick a REAL team from the loaded rosters (the switcher renders only when
  // the contract delivered them).  `.first()` absorbs the SSR duplicate (#716).
  const toggle = root.locator("button.team-switcher-toggle").first();
  await expect(toggle, "rosters must load for the team switcher to render").toBeVisible({ timeout: 60_000 });
  await toggle.click();
  const option = root.locator(".team-switcher-menu").first().locator('[role="option"]').first();
  await option.click();
  return root;
}

test("weekly IDP streaming: gate, real team, controls reach the backend, boards, 390 px, axe clean", async ({
  authedPage: page,
}, testInfo) => {
  const errors = [];
  page.on("pageerror", (e) => {
    if (!isNavigationAbortedFetch(e, page)) errors.push(e.message);
  });
  const calls = await mockEndpoints(page);
  const root = await openAdvisorWithTeam(page);

  await root.getByRole("radio", { name: "Weekly IDP streaming" }).click();
  const panel = page.getByTestId("idp-streaming");
  await expect(panel).toBeVisible();
  const rec = page.getByTestId("streaming-recommendation");
  await expect(rec).toBeVisible({ timeout: 30_000 });
  expect(calls.length).toBeGreaterThan(0);
  const first = calls[0];
  expect(first.teamOwnerId, "a team is always sent, never guessed").toBeTruthy();
  expect(first).toMatchObject({ horizonWeeks: 1, position: "ALL", capacity: 2, dynastyBudget: 0 });

  // Budget 0: one move, and the larger-budget plan names the second.
  await expect(page.getByTestId("streaming-larger-budget")).toContainText("Tyrell Gaines");

  // Raise the dynasty budget: the backend (not the page) returns the two-move plan.
  const budget = panel.getByLabel("Dynasty loss budget");
  await budget.fill("300");
  await budget.press("Enter");
  await expect(rec.getByTestId("streaming-moves")).toContainText("Andre Whitfield", { timeout: 30_000 });
  expect(calls.at(-1).dynastyBudget).toBe(300);
  await expect(rec).toContainText(/partial/);
  await expect(page.getByTestId("streaming-capacity-curve")).toContainText("Recommended");

  // The streaming board follows the backend's order and states unknowns.
  const board = panel.getByRole("table", { name: /Available IDP players/ });
  await expect(board.getByRole("row").nth(1)).toContainText(RECOMMEND.streamingBoard[0].name);
  // Protection is explained on the safe-to-drop board.
  const drops = panel.getByRole("table", { name: /classified by drop safety/ });
  await expect(drops).toContainText("Protected");
  await expect(page.getByText("Roster defenders without a projection")).toBeVisible();

  await noPageOverflow(page);
  const axe = await new AxeBuilder({ page }).withTags(TAGS).include('[data-testid="idp-streaming"]').analyze();
  await testInfo.attach("idp-streaming-axe", {
    body: JSON.stringify(axe.violations, null, 2),
    contentType: "application/json",
  });
  expect(axe.violations).toEqual([]);
  await panel.screenshot({ path: testInfo.outputPath("idp-streaming-recommend.png") });

  // DL only: the explicit no-move state, in plain language.
  await panel.getByRole("radio", { name: "DL" }).click();
  await expect(page.getByTestId("streaming-no-move")).toBeVisible({ timeout: 30_000 });
  await expect(page.getByTestId("streaming-no-move")).toContainText(
    "No legal add/drop improves your projected starting lineup this week.",
  );
  expect(calls.at(-1).position).toBe("DL");
  await noPageOverflow(page);

  expect(errors, "no uncaught page errors").toEqual([]);
});

test("weekly IDP streaming: no mode while its flag is off", async ({ authedPage: page }) => {
  await mockEndpoints(page, { streamingOff: true });
  // Wait for the gate probe's answer, so "no mode" is not just "not yet".
  const probed = page.waitForResponse(
    (r) => new URL(r.url()).pathname === "/api/waiver/streaming" && r.status() === 503,
  );
  const root = await openAdvisorWithTeam(page);
  await probed;
  await expect(root.getByTestId("advisor-team-context")).toBeVisible({ timeout: 30_000 });
  await expect(root.getByRole("radio", { name: "Best available" })).toHaveCount(0);
  await expect(root.getByRole("radio", { name: "Weekly IDP streaming" })).toHaveCount(0);
});
